document.addEventListener('DOMContentLoaded',()=>{
 'use strict';const R=window.RIA,esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),date=n=>new Date(Number(n)).toLocaleString('fa-IR',{dateStyle:'medium',timeStyle:'short'}),shell=R.shell({foot:'اطلاعات این صفحه خصوصی است.',artTitle:'وضعیت حساب، روشن و قابل پیگیری',artText:'دلیل تصمیم و مسیر بعدی حساب تو.'});
 async function api(action='',data){const r=await fetch('/api/auth/account-status'+action,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(15000)}),result=await r.json();if(!r.ok)throw Error(result.error||'دریافت اطلاعات انجام نشد');return result;}
 async function load(){try{const n=await api(),deleted=n.state==='deleted',active=n.state==='suspended';document.title=(deleted?'حساب حذف شده':active?'حساب تعلیق شده':'محدودیت برداشته شد')+' | رزومیت';R.swap(shell.view,'<section class="account-notice"><span class="badge">وضعیت حساب</span><h1 data-focus>'+(deleted?'این حساب حذف شده است':active?'استفاده از این حساب فعلاً ممکن نیست':'محدودیت حساب برداشته شده است')+'</h1><p>'+(deleted?'این حساب توسط مدیر با شناسهٔ <bdi>'+esc(n.actorCode)+'</bdi> حذف شده است.':active?'تا پایان تعلیق، دسترسی به داشبورد و صفحه‌های عمومی این حساب بسته است.':'می‌توانی دوباره از صفحهٔ ورود وارد حساب شوی.')+'</p><dl class="notice-facts"><div><dt>شناسهٔ حساب</dt><dd dir="ltr">'+esc(n.accountCode)+'</dd></div><div><dt>'+(active?'پایان تعلیق':'زمان تصمیم')+'</dt><dd>'+(active?(n.until?esc(date(n.until)):'تا بررسی و اعلام مدیریت'):esc(date(n.at)))+'</dd></div></dl><div class="notice-reason"><strong>دلیل اعلام‌شده</strong>\n'+esc(n.reason)+'</div>'+(n.review?'<section class="notice-review"><h2>درخواست بازبینی</h2><p>'+(n.review.status==='open'?'در صف بررسی پشتیبانی است.':n.review.status==='answered'?'پشتیبانی به درخواست پاسخ داده است.':'بررسی این گفت‌وگو بسته شده است.')+'</p>'+n.review.messages.map(m=>'<article class="notice-message" data-staff="'+!!m.staff+'"><strong>'+(m.staff?'پشتیبانی':'تو')+'</strong><p>'+esc(m.body)+'</p></article>').join('')+'</section>':active?'<form class="notice-review" id="review-form"><h2>درخواست بررسی مجدد</h2><label for="review-body">توضیح تو برای تیم بررسی</label><textarea id="review-body" name="body" required minlength="10" maxlength="2000"></textarea><button class="btn btn--primary" type="submit">ارسال درخواست بازبینی</button></form>':'')+(deleted?'<form class="notice-review" id="recreate-form"><h2>شروع دوباره</h2><p>ساخت حساب تازه، اطلاعات حذف‌شده را برنمی‌گرداند؛ حساب جدید بدون اطلاعات، صفحه‌ها و موجودی قبلی شروع می‌شود.</p><label class="notice-consent"><input type="checkbox" name="confirm" required>می‌دانم که حساب جدید خالی است و اطلاعات قبلی بازگردانده نمی‌شوند.</label><button class="btn btn--primary" type="submit">ساخت حساب تازه</button></form>':'')+'<p class="notice-error" role="status" id="notice-feedback"></p><div class="notice-actions">'+(!active&&!deleted?'<a class="btn btn--primary" href="/login/">ورود دوباره</a>':'')+'<button class="btn" id="notice-leave" type="button">ورود با حساب دیگر</button><a class="link" href="/contact/">ارتباط با ما</a></div></section>',root=>{
   const feedback=root.querySelector('#notice-feedback');for(const [id,action]of [['review-form','/review'],['recreate-form','/recreate']])root.querySelector('#'+id)?.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button');button.disabled=true;feedback.textContent='';try{const result=await api(action,id==='review-form'?{body:form.elements.body.value}:{confirm:form.elements.confirm.checked});if(result.redirect)location.assign(result.redirect);else await load();}catch(error){feedback.textContent=error.message;button.disabled=false;}});root.querySelector('#notice-leave').onclick=async()=>{try{await api('/leave',{});location.assign('/login/');}catch(error){feedback.textContent=error.message;}};
  });}catch(error){R.swap(shell.view,'<h1 data-focus>تأیید هویت لازم است</h1><p>'+esc(error.message)+'</p><a class="btn btn--primary" href="/login/">رفتن به ورود</a>');}}
 load();
});
